-- Centro ejecutivo de Dirección General.
create table if not exists public.general_executive_agreements(id uuid primary key default gen_random_uuid(),code text not null unique,title text not null,description text not null default '',responsible_direction text not null,due_date date,priority text not null default 'MEDIA',status text not null default 'PENDIENTE',progress numeric(5,2) not null default 0 check(progress between 0 and 100),created_by uuid references public.app_users(id),updated_by uuid references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.general_directives(id uuid primary key default gen_random_uuid(),code text not null unique,title text not null,directive_type text not null default 'DISPOSICION',issued_date date not null default current_date,effective_date date,responsible_direction text not null,content text not null,status text not null default 'VIGENTE',created_by uuid references public.app_users(id),created_at timestamptz not null default now());
create table if not exists public.general_executive_agenda(id uuid primary key default gen_random_uuid(),title text not null,event_type text not null default 'REUNION',starts_at timestamptz not null,ends_at timestamptz,location text not null default '',responsible_direction text not null default 'Dirección General',status text not null default 'PROGRAMADA',notes text not null default '',created_by uuid references public.app_users(id),created_at timestamptz not null default now());
create table if not exists public.general_communications(id uuid primary key default gen_random_uuid(),code text not null unique,subject text not null,communication_type text not null default 'INTERNA',recipient text not null,issued_date date not null default current_date,status text not null default 'BORRADOR',summary text not null default '',created_by uuid references public.app_users(id),created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['general_executive_agreements','general_directives','general_executive_agenda','general_communications'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
create sequence if not exists public.general_direction_seq start 1;

create or replace function public.list_general_direction(p_token text,p_year integer default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare u public.app_users;y integer:=coalesce(p_year,extract(year from current_date)::integer);result jsonb;
begin u:=public.hr_authenticated_user(p_token);if u.id is null or (u.role<>'Administrador' and not coalesce((u.permissions->>'ver_direccion_general')::boolean,false)) then return jsonb_build_object('success',false,'error','No autorizado.');end if;
select jsonb_build_object('success',true,'year',y,
'agreements',(select coalesce(jsonb_agg(to_jsonb(a) order by priority, due_date),'[]'::jsonb) from public.general_executive_agreements a where extract(year from a.created_at)=y),
'directives',(select coalesce(jsonb_agg(to_jsonb(d) order by issued_date desc),'[]'::jsonb) from public.general_directives d where extract(year from d.issued_date)=y),
'agenda',(select coalesce(jsonb_agg(to_jsonb(a) order by starts_at),'[]'::jsonb) from public.general_executive_agenda a where extract(year from a.starts_at)=y),
'communications',(select coalesce(jsonb_agg(to_jsonb(c) order by issued_date desc),'[]'::jsonb) from public.general_communications c where extract(year from c.issued_date)=y),
'metrics',jsonb_build_object(
'activeProjects',(select count(*) from public.technical_projects where project_year=y and lower(coalesce(work_status,'')) not in('terminada','finalizada')),
'investment',(select coalesce(sum(budgeted_amount),0) from public.technical_projects where project_year=y),
'paid',(select coalesce(sum(total_paid),0) from public.technical_projects where project_year=y),
'activeEmployees',(select count(*) from public.hr_employees where lower(coalesce(employment_status,'')) in('activo','fijo','carrera administrativa','temporal','interino','estatuto simplificado')),
'pendingAgreements',(select count(*) from public.general_executive_agreements where status not in('COMPLETADO','CANCELADO')),
'overdueAgreements',(select count(*) from public.general_executive_agreements where due_date<current_date and status not in('COMPLETADO','CANCELADO')),
'planningGoals',(select count(*) from public.planning_goals where extract(year from created_at)=y),
'financialPending',(select coalesce(sum(net_amount),0) from public.financial_payment_requests where status not in('PAGADA','RECHAZADA') and extract(year from created_at)=y),
'commercialCollected',(select coalesce(sum(amount),0) from public.commercial_payments where extract(year from payment_date)=y)
)) into result;return result;end$$;

create or replace function public.manage_general_direction(p_token text,p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare u public.app_users;new_id uuid;code text;allowed boolean;
begin u:=public.hr_authenticated_user(p_token);allowed:=u.role='Administrador' or coalesce((u.permissions->>'gestionar_direccion_general')::boolean,false);if u.id is null or not allowed then return jsonb_build_object('success',false,'error','No autorizado.');end if;
if p_action='CREATE_AGREEMENT' then code='AC-DG-'||extract(year from current_date)::int||'-'||lpad(nextval('public.general_direction_seq')::text,5,'0');insert into public.general_executive_agreements(code,title,description,responsible_direction,due_date,priority,created_by) values(code,p_data->>'title',coalesce(p_data->>'description',''),p_data->>'responsible_direction',nullif(p_data->>'due_date','')::date,coalesce(p_data->>'priority','MEDIA'),u.id) returning id into new_id;
elsif p_action='UPDATE_AGREEMENT' then update public.general_executive_agreements set status=coalesce(p_data->>'status',status),progress=coalesce(nullif(p_data->>'progress','')::numeric,progress),description=coalesce(p_data->>'description',description),updated_by=u.id,updated_at=now() where id=(p_data->>'id')::uuid returning id into new_id;
elsif p_action='CREATE_DIRECTIVE' then code='DG-'||extract(year from current_date)::int||'-'||lpad(nextval('public.general_direction_seq')::text,5,'0');insert into public.general_directives(code,title,directive_type,issued_date,effective_date,responsible_direction,content,created_by) values(code,p_data->>'title',coalesce(p_data->>'directive_type','DISPOSICION'),coalesce(nullif(p_data->>'issued_date','')::date,current_date),nullif(p_data->>'effective_date','')::date,p_data->>'responsible_direction',p_data->>'content',u.id) returning id into new_id;
elsif p_action='CREATE_AGENDA' then insert into public.general_executive_agenda(title,event_type,starts_at,ends_at,location,responsible_direction,notes,created_by) values(p_data->>'title',coalesce(p_data->>'event_type','REUNION'),(p_data->>'starts_at')::timestamptz,nullif(p_data->>'ends_at','')::timestamptz,coalesce(p_data->>'location',''),coalesce(p_data->>'responsible_direction','Dirección General'),coalesce(p_data->>'notes',''),u.id) returning id into new_id;
elsif p_action='CREATE_COMMUNICATION' then code='COM-DG-'||extract(year from current_date)::int||'-'||lpad(nextval('public.general_direction_seq')::text,5,'0');insert into public.general_communications(code,subject,communication_type,recipient,issued_date,status,summary,created_by) values(code,p_data->>'subject',coalesce(p_data->>'communication_type','INTERNA'),p_data->>'recipient',coalesce(nullif(p_data->>'issued_date','')::date,current_date),coalesce(p_data->>'status','BORRADOR'),coalesce(p_data->>'summary',''),u.id) returning id into new_id;
else return jsonb_build_object('success',false,'error','Acción no reconocida.');end if;return jsonb_build_object('success',true,'id',new_id,'code',code);exception when others then return jsonb_build_object('success',false,'error',sqlerrm);end$$;
grant execute on function public.list_general_direction(text,integer),public.manage_general_direction(text,text,jsonb) to anon,authenticated;
